import{_ as l,o as e,c as o,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"考拉記帳使用者協議","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/legal/terms.md","filePath":"v1/zh-HK/legal/terms.md"}'),t={name:"v1/zh-HK/legal/terms.md"};function i(n,a,p,s,h,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="考拉記帳使用者協議" tabindex="-1"><strong>考拉記帳</strong>使用者協議 <a class="header-anchor" href="#考拉記帳使用者協議" aria-label="Permalink to &quot;**考拉記帳**使用者協議&quot;">​</a></h1><p>更新日期：2026 年 04 月 24 日</p><p>生效日期：2026 年 04 月 24 日</p><p>本《考拉記帳使用者協議》（以下簡稱「本協議」）由【應用營運主體名稱】及其關聯方（以下簡稱「我們」）與使用 考拉記帳（Koala，以下簡稱「本應用」）的使用者（以下簡稱「你」）共同訂立。</p><p>在你開始使用本應用之前，請你務必審慎閱讀並充分理解本協議各條款內容。你點擊「同意／接受」或以任何方式實際使用本應用服務，即表示你已閱讀並同意接受本協議的約束。</p><h2 id="_1-定義" tabindex="-1"><strong>1. 定義</strong> <a class="header-anchor" href="#_1-定義" aria-label="Permalink to &quot;**1. 定義**&quot;">​</a></h2><ol><li><p>本應用：指 考拉記帳（Koala）客戶端軟件及其相關服務。</p></li><li><p>服務：指我們基於本應用向你提供的記帳、資料管理、匯入匯出、雲端同步（如有）、會員（如有）等功能與技術服務。</p></li><li><p>帳號：指你用於登入本應用服務的身份識別（例如使用 Apple 登入）。</p></li></ol><h2 id="_2-協議的範圍與變更" tabindex="-1"><strong>2. 協議的範圍與變更</strong> <a class="header-anchor" href="#_2-協議的範圍與變更" aria-label="Permalink to &quot;**2. 協議的範圍與變更**&quot;">​</a></h2><ol><li><p>本協議內容包括本協議正文，以及我們已發布或將來可能發布的與本應用相關的各類規則、公告、說明等。前述內容一經正式發布，均為本協議不可分割的組成部分。</p></li><li><p>我們有權在必要時修改本協議條款，並在本應用內或相關頁面進行提示。若你在修改後繼續使用本服務，即表示你已接受修改後的協議；若你不接受修改後的協議，你應停止使用本服務。</p></li></ol><h2 id="_3-帳號與使用規則" tabindex="-1"><strong>3. 帳號與使用規則</strong> <a class="header-anchor" href="#_3-帳號與使用規則" aria-label="Permalink to &quot;**3. 帳號與使用規則**&quot;">​</a></h2><ol><li><p>你應遵守法律法規及本協議約定使用本服務，不得利用本服務從事任何違法違規活動。</p></li><li><p>你應妥善保管你的登入憑證與裝置。因你自身原因導致的帳號被盜用或資料外洩風險，將由你自行承擔相應責任。</p></li><li><p>若你透過第三方帳號（例如 Apple）登入，我們會按第三方平台規則進行必要的授權與驗證。</p></li></ol><h2 id="_4-服務內容與使用限制" tabindex="-1"><strong>4. 服務內容與使用限制</strong> <a class="header-anchor" href="#_4-服務內容與使用限制" aria-label="Permalink to &quot;**4. 服務內容與使用限制**&quot;">​</a></h2><ol><li><p>本服務以「現狀」形式提供。我們會努力保障服務穩定，但不承諾服務不會中斷或不存在錯誤。</p></li><li><p>你理解並同意：我們可能基於產品迭代、營運策略或合規要求，對服務內容作出調整或停止部分功能，並在合理範圍內進行提示。</p></li><li><p>若你拒絕同意必要的協議或私隱政策，可能導致你無法使用本應用的核心功能或無法繼續使用本服務。</p></li></ol><h2 id="_5-付費服務-如有" tabindex="-1"><strong>5. 付費服務（如有）</strong> <a class="header-anchor" href="#_5-付費服務-如有" aria-label="Permalink to &quot;**5. 付費服務（如有）**&quot;">​</a></h2><ol><li><p>本應用可能提供訂閱／應用內購買等付費服務（例如會員權益）。具體內容、價格、週期、自動續費規則以購買頁面展示及相關說明為準。</p></li><li><p>你理解並同意：付款、退訂、退款等規則可能受 Apple App Store 等第三方平台規則約束。</p></li></ol><h2 id="_6-知識產權" tabindex="-1"><strong>6. 知識產權</strong> <a class="header-anchor" href="#_6-知識產權" aria-label="Permalink to &quot;**6. 知識產權**&quot;">​</a></h2><ol><li><p>本應用及其相關內容（包括但不限於頁面設計、圖示、文字、程式碼等）的知識產權歸我們或相關權利人所有。</p></li><li><p>未經我們書面許可，你不得以任何形式複製、修改、傳播或反向工程本應用或其內容。</p></li></ol><h2 id="_7-免責聲明與責任限制" tabindex="-1"><strong>7. 免責聲明與責任限制</strong> <a class="header-anchor" href="#_7-免責聲明與責任限制" aria-label="Permalink to &quot;**7. 免責聲明與責任限制**&quot;">​</a></h2><ol><li><p>因不可抗力、第三方原因、網絡環境、裝置故障等導致服務不可用或資料異常的，我們在法律允許範圍內不承擔由此產生的損失。</p></li><li><p>你理解記帳資料、匯入匯出檔案等由你自行維護備份。若你未進行備份而造成資料遺失，我們在法律允許範圍內不承擔責任。</p></li></ol><h2 id="_8-個人資料保護" tabindex="-1"><strong>8. 個人資料保護</strong> <a class="header-anchor" href="#_8-個人資料保護" aria-label="Permalink to &quot;**8. 個人資料保護**&quot;">​</a></h2><ol><li><p>我們非常重視你的個人資料保護。你在使用本服務時，我們將按照《考拉記帳私隱政策》處理你的個人資料。</p></li><li><p>《考拉記帳私隱政策》是本協議的重要組成部分，與本協議具有同等法律效力。</p></li></ol><h2 id="_9-適用法律與爭議解決" tabindex="-1"><strong>9. 適用法律與爭議解決</strong> <a class="header-anchor" href="#_9-適用法律與爭議解決" aria-label="Permalink to &quot;**9. 適用法律與爭議解決**&quot;">​</a></h2><ol><li><p>本協議的訂立、執行與解釋及爭議解決均適用中華人民共和國法律法規（不含衝突規範）。</p></li><li><p>因本協議引起的或與本協議有關的爭議，雙方應友好協商解決；協商不成的，任一方可向【合同履行地／營運主體所在地】有管轄權的人民法院提起訴訟。</p></li></ol><h2 id="_10-聯絡我們" tabindex="-1"><strong>10. 聯絡我們</strong> <a class="header-anchor" href="#_10-聯絡我們" aria-label="Permalink to &quot;**10. 聯絡我們**&quot;">​</a></h2><p>如你對本協議有任何疑問、意見或建議，請透過以下方式與我們聯絡：</p><p>● 營運主體：【考拉記帳】</p><p>● 聯絡電郵：ruanweidev@163.com</p><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1>',28)])])}const u=l(t,[["render",i]]);export{c as __pageData,u as default};
